script:
export const meta = {
  name: 's4hana-research',
  description: 'Research SAP S/4HANA functional scope per module area and draft the Atlas parity table',
  phases: [
    { title: 'Research', detail: 'one web-research agent per S/4HANA area' },
    { title: 'Synthesize', detail: 'compose the parity document' },
  ],
}

const ATLAS_MODULES = 'finance, inventory, procurement, sales, manufacturing, quality, maintenance, hr, projects, crm, reporting, admin, industry, core, frontend'

const AREAS = [
  {
    key: 'fi',
    title: 'Financial Accounting (FI)',
    focus: 'General Ledger and the Universal Journal (ACDOCA), Accounts Payable, Accounts Receivable, Asset Accounting, Bank & Cash Management, tax handling, financial statements, period-end close.',
    atlasScope: 'Universal-journal ledger with hierarchical configurable chart of accounts; strict double-entry (debits == credits per currency or rejected); posted entries immutable, corrections via reversing entries only; journal lines carry cost center, profit center, project dimensions; fiscal years/periods with open/closed states enforced at service AND DB level; multi-currency (transaction + functional currency, rates table, realized/unrealized FX accounts); AP (vendor bills, payment runs, aging); AR (invoices, receipts, dunning levels, aging); configurable tax codes (rate, jurisdiction, inclusive/exclusive) at line level; statements generated from the ledger never stored (Trial Balance, P&L, Balance Sheet, Cash Flow indirect); bank reconciliation via CSV statement import + match suggestions; asset accounting lite (asset register, straight-line and declining-balance depreciation runs posting journals).',
  },
  {
    key: 'co',
    title: 'Controlling (CO)',
    focus: 'Cost center accounting, profit center accounting, internal orders, product costing (CO-PC), margin analysis / profitability analysis (CO-PA), allocations and assessments, and how S/4HANA merged CO into the Universal Journal.',
    atlasScope: 'Journal lines carry cost center, profit center and project dimensions so all CO reporting is a projection of the universal journal; cost centers and profit centers with allocation rules; product costing fed by manufacturing (WIP journals, finish-to-stock); cost-center report and margin-by-product report generated from the ledger. Internal orders are not planned as a separate object (projects/WBS cover that role).',
  },
  {
    key: 'mm-pur',
    title: 'Procurement (MM-PUR)',
    focus: 'Vendor/supplier master, purchase requisitions, RFQs, purchase orders, goods receipt, invoice verification and 3-way match, approval/release strategies, contracts and scheduling agreements, source determination.',
    atlasScope: 'Vendor master (payment terms, currencies, approved items); Requisition -> RFQ -> PO -> Goods Receipt -> 3-way match -> AP bill chain; configurable approval threshold rules stored as data. Contracts, scheduling agreements and source determination are not in the v1 list.',
  },
  {
    key: 'mm-im-ewm',
    title: 'Inventory Management & Warehousing (MM-IM / EWM)',
    focus: 'Material master, stock types and movements, goods movements, physical inventory / cycle counting, material valuation (moving average, FIFO, standard), batch and serial number management; Extended Warehouse Management: storage bins, waves, handling units, putaway/picking strategies.',
    atlasScope: 'Items (stocked / non-stocked / service), lot & serial tracking, multi-UoM with conversions; multi-warehouse, multi-bin; stock moves as the single source of truth for every change; moving average AND FIFO costing per item category; COGS auto-posted via events; reorder points -> auto-draft requisitions; physical/cycle counts with variance posting. EWM waves, handling units and strategy engines are not in the v1 list.',
  },
  {
    key: 'sd',
    title: 'Sales & Distribution (SD)',
    focus: 'Customer master, pricing & condition technique, sales orders, available-to-promise (ATP), shipping and deliveries, billing, credit management, returns processing.',
    atlasScope: 'Customer master; condition-style pricing (price lists per currency / customer group / date range, discounts); Quote -> Order -> Delivery -> Invoice with partial shipments and backorders; simple ATP check against on-hand + on-order; credit-limit block at order confirmation; RMA returns with credit notes.',
  },
  {
    key: 'pp',
    title: 'Production Planning (PP)',
    focus: 'Bills of material, work centers, routings, production orders, MRP and MRP Live, capacity planning, plus what v1-grade systems typically omit (kanban, repetitive manufacturing, detailed scheduling/PPDS).',
    atlasScope: 'Multi-level versioned BOMs; work centers; routings with setup/run times; production orders (reserve materials, issue to WIP, finish to stock, WIP journals); MRP run exploding sales-order demand + reorder points against supply producing planned orders; rough capacity check (work-center load vs available hours).',
  },
  {
    key: 'qm-pm',
    title: 'Quality Management & Plant Maintenance (QM / PM-EAM)',
    focus: 'QM: inspection lots, inspection plans, results recording, usage decisions, quality notifications. PM/EAM: equipment and functional locations, maintenance notifications and orders, preventive maintenance plans, measurement points.',
    atlasScope: 'Inspection flag on goods receipt -> inspection lot -> accept/reject with stock disposition; equipment register; corrective and preventive (interval-based) maintenance orders. Inspection plans, usage-decision codes, functional locations and measurement points are not in the v1 list.',
  },
  {
    key: 'hcm',
    title: 'Human Capital Management (HCM / SuccessFactors)',
    focus: 'Organizational management, employee master data, time management, payroll, leave/absence management; how S/4HANA handles HR (embedded HCM vs SuccessFactors cloud).',
    atlasScope: 'Employees with masked compensation fields; departments, positions, org chart; leave types/accruals/approvals; time tracking with project & cost-center allocation; simple gross-to-net payroll posting a journal, explicitly flagged as not jurisdiction-compliant. Talent, recruiting, benefits and real payroll compliance are not in the v1 list.',
  },
  {
    key: 'ps',
    title: 'Project System (PS)',
    focus: 'Projects and WBS elements, networks/activities, project budgeting, time and expense posting to projects, settlement, results analysis.',
    atlasScope: 'Projects with WBS elements as costing objects; time and purchases postable to WBS; project cost report. Networks, scheduling, budgeting controls and settlement are not in the v1 list.',
  },
  {
    key: 'cross',
    title: 'Cross-cutting platform concepts',
    focus: 'The Universal Journal (ACDOCA) as single source of truth; document flow / document relationship browser; the Business Partner model (BP as single object for customer/vendor); output management; number ranges; the authorization concept (roles/profiles); multi-client architecture and SaaS multi-tenancy in S/4HANA Cloud.',
    atlasScope: 'Universal Journal pattern and document flow are MANDATORY inheritances (one append-only financial line-item table, FI/CO views as projections; every business document records predecessor/successor links with a UI chain viewer). Atlas keeps separate vendor and customer masters rather than a unified Business Partner (note this as a deliberate deviation). Row-level tenant_id multi-tenancy with non-bypassable session filter; JWT auth with roles -> permissions -> resources as data; append-only audit table via middleware; per-tenant document number sequences. Output management beyond basic document rendering is not in the v1 list.',
  },
  {
    key: 'ux-analytics',
    title: 'Fiori UX & Embedded Analytics',
    focus: 'Fiori design system and role-based launchpad (tiles, KPIs, spaces/pages), key Fiori app types (list report, object page, overview page), embedded analytics (CDS views, analytical queries, KPI tiles), and what makes the S/4HANA UX distinctive.',
    atlasScope: 'Fiori-inspired role-based home pages: each role sees tiles for its apps and KPIs; in-house component library (data grid, form builder, kanban, dashboard cards, document-flow viewer); role-based dashboards (cash position, AR/AP aging, inventory value, open orders, OTD%, WIP); generic report builder (entity + columns + filters + group-by -> JSON grid + CSV export).',
  },
  {
    key: 'industry',
    title: 'Industry Solutions approach',
    focus: 'How SAP delivers its ~25 industry solutions for S/4HANA (industry-specific functionality, activation via business functions, examples: retail, healthcare, EC&O construction, professional services, industrial manufacturing), and what an industry layer needs to vary.',
    atlasScope: 'YAML industry-template layer: terminology display overrides (Patient vs Customer, Job vs Production Order), chart-of-accounts preset, default tax codes, UoMs, enabled/disabled modules, typed custom fields (JSONB + metadata registry surfaced in forms, grids, report builder), approval presets, numbering formats; five shipped templates (manufacturing, retail, professional-services, healthcare, construction) applied idempotently at tenant creation.',
  },
]

const FINDINGS = {
  type: 'object',
  required: ['module', 'overview', 'capabilities', 'sources'],
  properties: {
    module: { type: 'string' },
    overview: { type: 'string', description: '3-6 sentence summary of what this S/4HANA area does and whether findings come from live web research or embedded knowledge' },
    capabilities: {
      type: 'array',
      minItems: 6,
      items: {
        type: 'object',
        required: ['capability', 'description', 'essential', 'atlas_v1', 'atlas_module', 'reason', 'later_path'],
        properties: {
          capability: { type: 'string' },
          description: { type: 'string', description: 'one line: what it does in S/4HANA' },
          essential: { type: 'boolean', description: 'would practitioners consider this core to the area' },
          atlas_v1: { type: 'string', enum: ['full', 'partial', 'out-of-scope'] },
          atlas_module: { type: 'string', description: 'Atlas module that owns it, or "-" if out-of-scope' },
          reason: { type: 'string', description: 'for partial/out-of-scope: one-line reason and the boundary; for full: may be empty' },
          later_path: { type: 'string', description: 'for partial/out-of-scope: one line on how it would be added later; for full: may be empty' },
        },
      },
    },
    sources: { type: 'array', items: { type: 'string' }, description: '2-6 URLs; empty if embedded-knowledge fallback was used' },
  },
}

const SYNTH = {
  type: 'object',
  required: ['full_count', 'partial_count', 'out_count', 'areas_web_researched', 'notes'],
  properties: {
    full_count: { type: 'number' },
    partial_count: { type: 'number' },
    out_count: { type: 'number' },
    areas_web_researched: { type: 'number' },
    notes: { type: 'string' },
  },
}

function researchPrompt(a) {
  return 'You are doing functional research for "Atlas ERP", an open-source ERP whose explicit benchmark is SAP S/4HANA. Your assigned S/4HANA area: ' + a.title + '.\n\n' +
    'TASK: Establish what this area actually covers in current S/4HANA (2025/2026), identify the 6-12 capabilities practitioners consider essential, and judge each against the planned Atlas v1 scope below.\n\n' +
    'METHOD: Use WebSearch (and WebFetch for promising pages) - 2 to 5 targeted searches. Prefer SAP Help Portal, SAP Community, and reputable ERP consulting sources. If web tools are unavailable or consistently fail, fall back to your embedded knowledge of S/4HANA and say so explicitly in the overview field.\n\n' +
    'COVER AT MINIMUM: ' + a.focus + '\n\n' +
    'PLANNED ATLAS V1 SCOPE FOR THIS AREA (judge full/partial/out-of-scope against THIS, not your own ideas):\n' + a.atlasScope + '\n\n' +
    'RULES:\n' +
    '- atlas_v1 = "full" when Atlas v1 plans the practitioner-essential core of the capability; "partial" when a meaningful but reduced subset is planned; "out-of-scope" when none of it is planned.\n' +
    '- Every "partial" and "out-of-scope" entry MUST have a non-empty reason (why cut / where the boundary sits) and later_path (how to add it later in one line).\n' +
    '- atlas_module must be one of: ' + ATLAS_MODULES + ', or "-" for out-of-scope.\n' +
    '- Be honest: if S/4HANA has an essential capability the Atlas plan misses entirely, include it as out-of-scope rather than omitting it.\n\n' +
    'Your final output is consumed by a script - return only the structured data.'
}

phase('Research')
log('Fanning out ' + AREAS.length + ' research agents across S/4HANA functional areas')
const results = await parallel(AREAS.map(a => () =>
  agent(researchPrompt(a), { label: 'research:' + a.key, phase: 'Research', schema: FINDINGS })
))
const ok = results.filter(Boolean)
log('Research complete: ' + ok.length + '/' + AREAS.length + ' areas returned findings')

phase('Synthesize')
const synthPrompt = 'You are composing the S/4HANA parity document for Atlas ERP (an open-source ERP benchmarked against SAP S/4HANA). Below is structured research JSON: one entry per S/4HANA functional area, each with an overview, capability list (with atlas_v1 status full/partial/out-of-scope, owning Atlas module, reason, later_path) and source URLs.\n\n' +
  'Write the file /tmp/atlas-research/s4hana-parity.md using the Write tool. Requirements:\n' +
  '1. Title: "# SAP S/4HANA → Atlas Parity Map". Intro paragraph: purpose of the doc, that Atlas v1 scope is derived from this benchmark, and the research date ' + args.date + '. State per the methodology which areas were web-researched vs built from the embedded baseline (check each overview).\n' +
  '2. A "Mandatory design inheritances" section stating the two hardcoded S/4HANA principles: (a) Universal Journal pattern - one append-only financial line-item table as single source of truth, all FI/CO views are projections, never separately stored totals; (b) Document flow - every business document records predecessor/successor links and the UI can render the full chain.\n' +
  '3. A summary table: per S/4HANA area, counts of full / partial / out-of-scope.\n' +
  '4. One section per area in the order given, each containing the overview (1 short paragraph) and a parity table with columns: S/4HANA capability | Atlas v1 | Atlas module | Notes. The Notes cell merges reason and later_path ("reason. Later: later_path."). Mark essential capabilities by bolding their name. Keep every partial/out-of-scope reason and later_path - that is the contract of this document.\n' +
  '5. A final "Sources" appendix grouping the URLs per area (note areas that used embedded-knowledge fallback).\n' +
  '6. Professional tone - this lands in a public repo. No first person.\n\n' +
  'After writing the file, return the counts (full/partial/out-of-scope totals across all areas, number of web-researched areas) and one notes line on anything surprising.\n\nRESEARCH JSON:\n' + JSON.stringify(ok)
const synth = await agent(synthPrompt, { label: 'synthesize:parity-doc', phase: 'Synthesize', schema: SYNTH })

return {
  docPath: '/tmp/atlas-research/s4hana-parity.md',
  areasResearched: ok.length,
  areasFailed: AREAS.length - ok.length,
  ...synth,
}
